package dev.survivorcreator.hudscale;
import java.lang.reflect.*;
public final class HudScale {
 private static final java.util.concurrent.ConcurrentHashMap<String,Method> METHODS=new java.util.concurrent.ConcurrentHashMap<>();
 private static final ThreadLocal<Frame> CURRENT=new ThreadLocal<>();
 public static final class Frame {Object pose;Frame parent;int width,height;Frame(Object p,int w,int h){pose=p;width=w;height=h;parent=CURRENT.get();}}
 private static Object invoke(Object receiver,String name,Object...args){try{Class<?> c=receiver instanceof Class<?> k?k:receiver.getClass();String key=c.getName()+"#"+name+"#"+args.length;Method found=METHODS.get(key);if(found==null){for(Method m:c.getMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){found=m;METHODS.put(key,m);break;}}if(found==null)throw new NoSuchMethodException(name);return found.invoke(receiver instanceof Class<?>?null:receiver,args);}catch(ReflectiveOperationException e){throw new IllegalStateException(name,e);}}
 private static Object window(){try{return invoke(invoke(Class.forName("net.minecraft.client.Minecraft"),"getInstance"),"getWindow");}catch(ClassNotFoundException e){throw new IllegalStateException(e);}}
 public static double ratio(double current,int width,int height){int target=Math.min(3,Math.max(1,Math.min(width/320,height/240)));return target/Math.max(1,current);}
 public static Object begin(Object input){Object gui=input;if(!input.getClass().getName().equals("net.minecraft.client.gui.GuiGraphics"))gui=invoke(input,"getGuiGraphics");Object win=window();int width=((Number)invoke(win,"getWidth")).intValue(),height=((Number)invoke(win,"getHeight")).intValue();double current=((Number)invoke(win,"getGuiScale")).doubleValue(),factor=ratio(current,width,height);double target=current*factor;if(CURRENT.get()!=null)factor=1;Object pose=invoke(gui,"pose");invoke(pose,"pushPose");try{invoke(pose,"scale",(float)factor,(float)factor,1f);Frame f=new Frame(pose,(int)Math.ceil(width/target),(int)Math.ceil(height/target));CURRENT.set(f);return f;}catch(RuntimeException e){invoke(pose,"popPose");throw e;}}
 public static void end(Object scope){if(scope instanceof Frame f){try{invoke(f.pose,"popPose");}finally{if(f.parent==null)CURRENT.remove();else CURRENT.set(f.parent);}}}
 public static int width(Object receiver){Frame f=CURRENT.get();if(f!=null)return f.width;try{return ((Number)invoke(receiver,"guiWidth")).intValue();}catch(IllegalStateException ignored){return ((Number)invoke(receiver,"getGuiScaledWidth")).intValue();}}
 public static int height(Object receiver){Frame f=CURRENT.get();if(f!=null)return f.height;try{return ((Number)invoke(receiver,"guiHeight")).intValue();}catch(IllegalStateException ignored){return ((Number)invoke(receiver,"getGuiScaledHeight")).intValue();}}
 public static Object rCall(Object receiver,String name,Object[] args){if(args.length==0&&CURRENT.get()!=null){if(name.equals("guiWidth")||name.equals("getGuiScaledWidth"))return width(receiver);if(name.equals("guiHeight")||name.equals("getGuiScaledHeight"))return height(receiver);}try{return Class.forName("dev.zomboid.firstaid.R").getMethod("call",Object.class,String.class,Object[].class).invoke(null,receiver,name,args);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
}
